PREMIUM_UI = r"""
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>TrustShield AI — Content Moderation Pipeline</title>
<style>
:root{
  --bg:#f3eee7;--ink:#2d241f;--muted:#746a61;--panel:#fffaf2;--soft:#eee6da;--line:#ded2c3;
  --primary:#c96442;--primary2:#9f4f33;--cyan:#6b8f89;--green:#2f8f6b;--amber:#b7791f;--red:#c2413c;
  --navy:#2d241f;--shadow:0 24px 70px rgba(76,52,38,.12);--radius:24px;
}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:linear-gradient(135deg,#f3eee7,#eee5d8 46%,#f8f3ea);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}.page{min-height:100vh;position:relative;overflow:hidden}.page:before,.page:after{pointer-events:none}.pageTexture{position:fixed;inset:0;pointer-events:none;opacity:.35;background-image:radial-gradient(circle at 1px 1px,rgba(76,52,38,.08) 1px,transparent 0);background-size:22px 22px;z-index:-1}.page:before{content:"";position:absolute;inset:-220px -120px auto auto;width:560px;height:560px;border-radius:50%;background:radial-gradient(circle,rgba(201,100,66,.18),transparent 68%);z-index:-1}.page:after{content:"";position:absolute;left:-180px;top:360px;width:520px;height:520px;border-radius:50%;background:radial-gradient(circle,rgba(107,143,137,.16),transparent 68%);z-index:-1}.nav{position:sticky;top:0;z-index:20;background:rgba(255,250,242,.82);backdrop-filter:blur(18px);border-bottom:1px solid rgba(229,231,239,.75)}.navIn{max-width:1200px;margin:auto;padding:16px 24px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px;font-weight:950;letter-spacing:-.03em}.logo{width:42px;height:42px;border-radius:14px;background:linear-gradient(135deg,#2d241f,var(--primary));display:grid;place-items:center;color:white;box-shadow:0 16px 38px rgba(201,100,66,.24)}.brand small{display:block;color:var(--muted);font-size:12px;font-weight:750;letter-spacing:0}.links{display:flex;align-items:center;gap:18px}.links a{color:var(--muted);text-decoration:none;font-size:14px;font-weight:800}.btn{border:0;border-radius:13px;padding:11px 16px;font-weight:900;cursor:pointer;background:linear-gradient(135deg,var(--primary),#d9825f);color:white;box-shadow:0 14px 34px rgba(201,100,66,.20);transition:.18s}.btn:hover{transform:translateY(-1px);box-shadow:0 18px 44px rgba(201,100,66,.26)}.btn.secondary{background:var(--panel);color:var(--ink);border:1px solid var(--line);box-shadow:none}.btn.ghost{background:#f7efe5;color:var(--ink);border:1px solid var(--line);box-shadow:none}.btn.warn{background:var(--amber);box-shadow:none}.btn.danger{background:var(--red);box-shadow:none}.hero{max-width:1200px;margin:auto;padding:78px 24px 58px;display:grid;grid-template-columns:1fr 500px;gap:48px;align-items:center}.eyebrow{display:inline-flex;align-items:center;gap:8px;padding:9px 13px;border-radius:999px;background:#f4e5d9;color:#9f4f33;font-weight:900;font-size:13px}.hero h1{font-size:clamp(46px,6.5vw,76px);line-height:.98;letter-spacing:-.065em;margin:22px 0 18px}.hero h1 span{background:linear-gradient(90deg,#2d241f,var(--primary),#6b8f89);-webkit-background-clip:text;background-clip:text;color:transparent}.lead{font-size:18px;line-height:1.75;color:var(--muted);max-width:670px}.heroActions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}.trustRow{display:flex;gap:20px;flex-wrap:wrap;margin-top:30px;color:var(--muted);font-size:14px}.trustRow b{color:var(--ink)}.preview{background:linear-gradient(180deg,#2d241f,#46362d);border-radius:32px;padding:18px;box-shadow:0 34px 90px rgba(76,52,38,.22);color:#fffaf2;position:relative;overflow:hidden}.preview:before{content:"";position:absolute;right:-80px;top:-80px;width:240px;height:240px;border-radius:50%;background:rgba(201,100,66,.20)}.previewTop{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.dots{display:flex;gap:7px}.dots span{width:10px;height:10px;border-radius:50%;background:#8b7a6b}.screenGrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.previewCard{background:rgba(255,250,242,.10);border:1px solid rgba(255,250,242,.14);border-radius:18px;padding:14px;backdrop-filter:blur(12px)}.previewCard.large{grid-column:1/-1}.bar{height:8px;background:rgba(255,255,255,.10);border-radius:99px;overflow:hidden;margin-top:9px}.bar span{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,var(--green),var(--amber),var(--red))}.features{max-width:1200px;margin:auto;padding:24px}.sectionHead{display:flex;align-items:end;justify-content:space-between;margin-bottom:18px}.sectionHead h2{margin:0;font-size:34px;letter-spacing:-.045em}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:22px;box-shadow:var(--shadow)}.icon{width:42px;height:42px;border-radius:14px;background:var(--soft);display:grid;place-items:center;font-size:20px;margin-bottom:14px}.card h3{margin:0 0 8px}.card p{color:var(--muted);line-height:1.6;margin:0}.workflow{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.step{position:relative;background:var(--panel);border:1px solid var(--line);border-radius:22px;padding:18px;box-shadow:var(--shadow)}.stepNum{width:32px;height:32px;border-radius:11px;background:#f4e5d9;color:#9f4f33;display:grid;place-items:center;font-weight:950;margin-bottom:12px}.app{display:none;min-height:calc(100vh - 75px)}.app.active{display:block}.layout{display:grid;grid-template-columns:260px 1fr;max-width:1440px;margin:auto}.sidebar{min-height:calc(100vh - 75px);border-right:1px solid var(--line);padding:22px;background:rgba(255,255,255,.62)}.sideTitle{font-size:12px;text-transform:uppercase;color:var(--muted);font-weight:900;margin:14px 0 8px}.sideItem{padding:11px 12px;border-radius:12px;color:#334155;font-weight:800;margin-bottom:6px}.sideItem.active{background:#f4e5d9;color:#9f4f33}.workspace{padding:24px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:18px}.topbar h2{margin:0;font-size:30px;letter-spacing:-.04em}.dashGrid{display:grid;grid-template-columns:390px 1fr;gap:18px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:24px;padding:20px;box-shadow:var(--shadow)}label{display:block;margin:13px 0 7px;font-weight:900;font-size:13px;color:#344054}textarea,select,input{width:100%;border:1px solid var(--line);border-radius:13px;padding:12px;font:inherit;background:var(--panel);color:var(--ink);outline:none}textarea:focus,select:focus,input:focus{border-color:#d9825f;box-shadow:0 0 0 4px rgba(201,100,66,.10)}textarea{min-height:112px;resize:vertical}.mini{min-height:72px}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.summary{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}.pill{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:#f7efe5;border-radius:999px;padding:7px 10px;font-size:13px;font-weight:900}.allow{color:var(--green)}.human_review{color:var(--amber)}.auto_action,.urgent_escalation{color:var(--red)}.scores{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.score{border:1px solid var(--line);background:var(--panel);border-radius:16px;padding:12px}.scoreTop{display:flex;justify-content:space-between;font-size:13px}.score .bar{background:#e5e7eb}.reason{color:var(--muted);line-height:1.6}.raw{max-height:300px;overflow:auto;background:#2d241f;color:#fff4e6;border-radius:16px;padding:14px;font-size:12px}.kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:18px 0}.kpi b{font-size:32px}.queueItem{border:1px solid var(--line);border-radius:16px;padding:14px;margin-top:10px;background:#fff}.modal{display:none;position:fixed;inset:0;background:rgba(45,36,31,.46);z-index:50;align-items:center;justify-content:center;padding:20px}.modal.active{display:flex}.modalBox{width:min(430px,100%);background:var(--panel);border-radius:24px;padding:24px;box-shadow:0 35px 90px rgba(15,23,42,.28)}.toast{display:none;position:fixed;right:22px;bottom:22px;z-index:70;background:#2d241f;color:#fffaf2;border-radius:14px;padding:12px 14px}.toast.active{display:block}@media(max-width:1000px){.hero,.dashGrid,.layout,.cards,.workflow{grid-template-columns:1fr}.sidebar{display:none}.links a{display:none}.preview{order:-1}.scores,.kpis{grid-template-columns:1fr}.hero{padding-top:48px}}
</style>
</head>
<body>
<div class="pageTexture"></div><div class="page" id="landing">
<nav class="nav"><div class="navIn"><div class="brand"><div class="logo">🛡️</div><div>TrustShield AI<small>Calm Moderation Workspace</small></div></div><div class="links"><a href="#features">Features</a><a href="#workflow">Workflow</a><a href="/docs">API Docs</a><button class="btn secondary" onclick="openSignIn()">Sign In</button><button class="btn" onclick="getStarted()">Get Started</button></div></div></nav>
<header class="hero"><div><span class="eyebrow">✦ AI moderation workspace</span><h1>Moderation that feels <span>calm, clear, and controlled.</span></h1><p class="lead">A warm, focused AI workspace for classifying content, applying policy, routing review cases, and keeping every moderation decision explainable.</p><div class="heroActions"><button class="btn" onclick="getStarted()">Get Started</button><button class="btn secondary" onclick="openSignIn()">Sign In</button></div><div class="trustRow"><span><b>7</b> harm categories</span><span><b>3</b> platform policies</span><span><b>Human</b> review queue</span></div></div><div class="preview"><div class="previewTop"><b>Decision Preview</b><div class="dots"><span></span><span></span><span></span></div></div><div class="screenGrid"><div class="previewCard large"><small>Primary category</small><h3>Harassment · 0.91</h3><div class="bar"><span style="width:91%"></span></div></div><div class="previewCard"><small>Routing</small><h3>Auto action</h3></div><div class="previewCard"><small>Policy</small><h3>children_app</h3></div><div class="previewCard large"><small>Reasoning</small><p style="color:#e7d9c8">Targets another user with degrading language and harmful intent.</p></div></div></div></header>
<section class="features" id="features"><div class="sectionHead"><h2>Built for Assignment 10 requirements</h2></div><div class="cards"><div class="card"><div class="icon">🧠</div><h3>Context-aware AI</h3><p>Uses content, user history, platform, and conversation context before deciding.</p></div><div class="card"><div class="icon">⚖️</div><h3>Policy routing</h3><p>Different thresholds for children, social media, and adult discussion platforms.</p></div><div class="card"><div class="icon">👥</div><h3>Human review</h3><p>Ambiguous cases are queued with AI reasoning and exact offending segments.</p></div></div></section>
<section class="features" id="workflow"><div class="sectionHead"><h2>System workflow</h2></div><div class="workflow"><div class="step"><div class="stepNum">1</div><b>Submit content</b><p class="reason">Text, platform, history, and thread context.</p></div><div class="step"><div class="stepNum">2</div><b>Classify</b><p class="reason">Scores across seven harm categories.</p></div><div class="step"><div class="stepNum">3</div><b>Route</b><p class="reason">Allow, review, auto-remove, or escalate.</p></div><div class="step"><div class="stepNum">4</div><b>Audit</b><p class="reason">Every decision is stored with explanation.</p></div></div></section>
</div>
<div class="app" id="app"><nav class="nav"><div class="navIn"><div class="brand"><div class="logo">🛡️</div><div>TrustShield AI<small>Moderator Dashboard</small></div></div><button class="btn secondary" onclick="showLanding()">Back to Home</button></div></nav><div class="layout"><aside class="sidebar"><div class="sideTitle">Workspace</div><div class="sideItem active">Moderation Studio</div><div class="sideItem">Review Queue</div><div class="sideItem">Policy Config</div><div class="sideItem">Evaluation</div><div class="sideTitle">Status</div><div class="sideItem" id="providerBadge">Provider: checking</div></aside><main class="workspace"><div class="topbar"><div><h2>Moderation Studio</h2><p class="reason" style="margin:5px 0 0">Test the pipeline and inspect explainable decisions.</p></div><button class="btn ghost" onclick="runEvaluation()">Run Evaluation</button></div><section class="dashGrid"><div class="panel"><h3>Submit Content</h3><label>Content</label><textarea id="content">You are useless and should disappear.</textarea><div class="row"><div><label>Platform</label><select id="platform"><option>children_app</option><option>social_media</option><option>adult_discussion_platform</option></select></div><div><label>Scenario</label><select id="scenario" onchange="loadScenario()"><option>Harassment</option><option>Movie Quote</option><option>Spam</option><option>Self Harm</option><option>Safe Slang</option></select></div></div><label>Conversation Context</label><textarea id="context" class="mini">Two students are arguing in a classroom thread.</textarea><label>User History</label><textarea id="history" class="mini">User has 2 previous warnings for harassment.</textarea><button class="btn" onclick="moderate()">Run Moderation</button></div><div class="panel"><h3>Decision Result</h3><div id="summary" class="summary"><span class="pill">Waiting for analysis</span></div><div id="scores" class="scores"></div><h4>Reasoning</h4><p id="reason" class="reason">No decision yet.</p><h4>Raw JSON</h4><pre id="raw" class="raw">{}</pre></div></section><section class="kpis"><div class="panel kpi"><span class="reason">Pending Review</span><br><b id="queueCount">0</b></div><div class="panel kpi"><span class="reason">Evaluation</span><br><b id="evalScore">—</b></div><div class="panel kpi"><span class="reason">Current Route</span><br><b id="routeScore">—</b></div></section><section class="panel"><h3>Human Review Queue</h3><div id="queue">Loading...</div></section></main></div></div>
<div class="modal" id="signIn"><div class="modalBox"><h2>Sign In</h2><p class="reason">Demo login for moderators.</p><label>Email</label><input id="email" value="admin@trustshield.ai"><label>Password</label><input id="password" type="password" value="admin123"><button class="btn" onclick="login()">Sign In</button> <button class="btn secondary" onclick="closeSignIn()">Cancel</button></div></div><div class="toast" id="toast"></div>
<script>
const $=id=>document.getElementById(id);const scenarios={"Harassment":["You are useless and should disappear.","children_app","Two students are arguing in a classroom thread.","User has 2 previous warnings for harassment."],"Movie Quote":["The villain in the movie said, 'I will kill you.'","social_media","Movie quote discussion.",""],"Spam":["Buy followers now! Click this link!","social_media","",""],"Self Harm":["I want to die and kill myself.","social_media","User is posting alone late at night.",""],"Safe Slang":["That was a killer performance.","social_media","Music performance review.",""]};
function toast(t){const e=$('toast');e.textContent=t;e.classList.add('active');setTimeout(()=>e.classList.remove('active'),2200)}function getStarted(){$('landing').style.display='none';$('app').classList.add('active');loadStatus();loadQueue()}function showLanding(){$('landing').style.display='block';$('app').classList.remove('active')}function openSignIn(){$('signIn').classList.add('active')}function closeSignIn(){$('signIn').classList.remove('active')}function login(){closeSignIn();getStarted();toast('Signed in as demo moderator')}function loadScenario(){const s=scenarios[$('scenario').value];$('content').value=s[0];$('platform').value=s[1];$('context').value=s[2];$('history').value=s[3]}
async function loadStatus(){try{const s=await(await fetch('/')).json();$('providerBadge').textContent='Provider: '+s.classifier_provider+(s.groq_configured?' ready':' needs GROQ_API_KEY');if(!s.groq_configured)renderError('GROQ_API_KEY is not configured. Add it to .env or export it, then restart the server.');}catch(e){$('providerBadge').textContent='Provider: unavailable'}}
async function moderate(){const payload={content:$('content').value,platform:$('platform').value,conversation_context:$('context').value,user_history:$('history').value};const r=await fetch('/moderate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok){renderError(d.detail||'Moderation request failed.');toast('Moderation failed');return}render(d);await loadQueue();toast('Moderation complete')}function render(d){$('providerBadge').textContent='Provider: '+d.classifier_provider;$('routeScore').textContent=d.routing;$('summary').innerHTML=`<span class="pill">${d.primary_category}</span><span class="pill">${d.confidence}</span><span class="pill ${d.routing}">${d.routing}</span><span class="pill">${d.final_decision}</span><span class="pill">${d.classifier_provider}</span>`;$('scores').innerHTML=Object.entries(d.categories).map(([k,v])=>`<div class="score"><div class="scoreTop"><b>${k}</b><span>${v}</span></div><div class="bar"><span style="width:${Math.round(v*100)}%"></span></div></div>`).join('');$('reason').textContent=`${d.reasoning} Offending segment: ${d.offending_segment||'none'} · Policy: ${d.policy_applied}`;$('raw').textContent=JSON.stringify(d,null,2)}function renderError(message){$('routeScore').textContent='blocked';$('summary').innerHTML='<span class="pill urgent_escalation">Configuration required</span>';$('scores').innerHTML='';$('reason').textContent=message;$('raw').textContent=JSON.stringify({error:message},null,2)}
async function loadQueue(){try{const q=await(await fetch('/review-queue')).json();$('queueCount').textContent=q.length;$('queue').innerHTML=q.length?q.map(x=>`<div class="queueItem"><b>${esc(x.ai_decision.primary_category)}</b> · <span class="${x.ai_decision.routing}">${x.ai_decision.routing}</span><p class="reason">${esc(x.ai_decision.reasoning)}</p><button class="btn secondary" onclick="review('${x.case_id}','allow')">Allow</button> <button class="btn warn" onclick="review('${x.case_id}','warn')">Warn</button> <button class="btn danger" onclick="review('${x.case_id}','remove')">Remove</button></div>`).join(''):'No pending cases.'}catch(e){$('queue').textContent='Review queue unavailable.'}}async function review(id,decision){await fetch('/review/'+id,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({moderator_decision:decision,moderator_notes:'Reviewed in UI'})});await loadQueue();toast('Review saved')}async function runEvaluation(){const r=await fetch('/evaluate',{method:'POST'});const e=await r.json();if(!r.ok){renderError(e.detail||'Evaluation failed.');toast('Evaluation failed');return}$('evalScore').textContent=e.passed+'/'+e.total;toast(`Evaluation: ${e.passed}/${e.total} passed`)}function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
</script>
</body>
</html>
"""
